import { createHash } from 'node:crypto';

export const SOUND_GENERATION_ENDPOINT = 'https://api.elevenlabs.io/v1/sound-generation';
export const SOUND_GENERATION_MODEL_ID = 'eleven_text_to_sound_v2';
export const SOUND_GENERATION_OUTPUT_FORMAT = 'mp3_44100_192';
export const SOUND_GENERATION_PROMPT_INFLUENCE = 0.3;

/** Every field capable of changing generated bytes belongs in this contract. */
export const SOUND_GENERATION_CONTRACT = {
  schemaVersion: 1,
  endpoint: SOUND_GENERATION_ENDPOINT,
  modelId: SOUND_GENERATION_MODEL_ID,
  outputFormat: SOUND_GENERATION_OUTPUT_FORMAT,
  promptInfluence: SOUND_GENERATION_PROMPT_INFLUENCE,
  promptComposition: 'sonicIdentity + U+0020 + entry.prompt',
  durationSource: 'catalog.durationSeconds',
  loopSource: 'catalog.loop',
  requestBodySchemaVersion: 1,
  responseValidation: 'audio/mpeg + ID3-or-MP3-frame-sync',
} as const;

export const SOUND_GENERATION_CONTRACT_SHA256 = createHash('sha256')
  .update(JSON.stringify(SOUND_GENERATION_CONTRACT))
  .digest('hex');
